import AppKit
import EspazioCore

/// Watches the general pasteboard for copied text (opt-in). Checks only the change counter, a
/// cheap integer read, twice a second. Items flagged by password managers and other apps as
/// concealed, transient or auto-generated (nspasteboard.org conventions) are never recorded.
@MainActor
public final class ClipboardMonitor {
    public var onCopy: ((String) -> Void)?
    private var timer: Timer?
    private var changeCount = NSPasteboard.general.changeCount

    static let ignoredTypes: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword", "de.petermaurer.TransientPasteboardType",
    ]

    public init() {}

    public func start() {
        guard timer == nil else { return }
        changeCount = NSPasteboard.general.changeCount
        let timer = Timer(timeInterval: 0.5, repeats: true) { [weak self] _ in
            MainActor.assumeIsolated { self?.check() }
        }
        timer.tolerance = 0.25
        RunLoop.main.add(timer, forMode: .common)
        self.timer = timer
    }

    public func stop() {
        timer?.invalidate()
        timer = nil
    }

    /// Puts a text back on the clipboard (it becomes the most recent entry again).
    public func copy(_ text: String) {
        let pasteboard = NSPasteboard.general
        pasteboard.clearContents()
        pasteboard.setString(text, forType: .string)
    }

    private func check() {
        let pasteboard = NSPasteboard.general
        guard pasteboard.changeCount != changeCount else { return }
        changeCount = pasteboard.changeCount
        let types = Set((pasteboard.types ?? []).map(\.rawValue))
        guard types.isDisjoint(with: Self.ignoredTypes), let text = pasteboard.string(forType: .string) else { return }
        onCopy?(text)
    }
}
